mod solution;

fn main() {
    let cases = [
    (r#"[170,45,75,90,802,24,2,66]"#, r#"2,24,45,66,75,90,170,802"#),
    (r#"[10,1,0]"#, r#"0,1,10"#),
    (r#"
[10,1,0]
"#, r#"0,1,10"#),
    (r#"  
[170,45,75,90,802,24,2,66]
  "#, r#"2,24,45,66,75,90,170,802"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS radix-sort");
}
